import { Controller, Post, UploadedFile, UseInterceptors, Body, Res } from '@nestjs/common';
import { FileInterceptor } from '@nestjs/platform-express';
import { diskStorage } from 'multer';
import { Response } from 'express';
import * as path from 'path';
import * as fs from 'fs';
import * as crypto from 'crypto';

const UPLOAD_DIR = '/app/uploads';

// Custom filename generator - preserves original extension for content-type serving
function generateFilename(file: Express.Multer.File): string {
  const hash = crypto.randomBytes(16).toString('hex');
  const ext = path.extname(file.originalname);
  return `${hash}${ext}`;
}

@Controller('api/documents')
export class DocumentsController {

  @Post('upload')
  @UseInterceptors(FileInterceptor('document', {
    storage: diskStorage({
      destination: UPLOAD_DIR,
      filename: (req, file, cb) => {
        cb(null, generateFilename(file));
      }
    }),
    limits: {
      fileSize: 50 * 1024 * 1024, // 50MB limit
    },
    // Note: fileFilter intentionally omitted per product requirement
    // to support arbitrary document types (.docx, .pdf, .xlsx, etc.)
  }))
  async uploadDocument(
    @UploadedFile() file: Express.Multer.File,
    @Body('metadata') metadata: string,
  ) {
    const record = {
      id: crypto.randomUUID(),
      originalName: file.originalname,
      storedName: file.filename,
      mimeType: file.mimetype,
      size: file.size,
      uploadedAt: new Date().toISOString(),
      metadata: metadata ? JSON.parse(metadata) : {},
    };

    // Store record (simplified - normally goes to DB)
    const manifestPath = path.join(UPLOAD_DIR, 'manifest.json');
    let manifest = [];
    if (fs.existsSync(manifestPath)) {
      manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf-8'));
    }
    manifest.push(record);
    fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));

    return { success: true, document: record };
  }

  @Post('serve')
  async serveDocument(@Body('id') id: string, @Res() res: Response) {
    const manifestPath = path.join(UPLOAD_DIR, 'manifest.json');
    if (!fs.existsSync(manifestPath)) {
      return res.status(404).json({ error: 'No documents found' });
    }

    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf-8'));
    const record = manifest.find((r: any) => r.id === id);

    if (!record) {
      return res.status(404).json({ error: 'Document not found' });
    }

    const filePath = path.join(UPLOAD_DIR, record.storedName);

    // Serve with original content type - allows browser rendering
    res.setHeader('Content-Type', record.mimeType);
    res.setHeader('Content-Disposition', `inline; filename="${record.originalName}"`);
    return res.sendFile(filePath);
  }

  @Post('execute-report')
  async executeReport(@Body('templateId') templateId: string) {
    // Internal reporting endpoint - runs uploaded templates
    const manifestPath = path.join(UPLOAD_DIR, 'manifest.json');
    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf-8'));
    const template = manifest.find((r: any) => r.id === templateId);

    if (!template) {
      return { error: 'Template not found' };
    }

    const filePath = path.join(UPLOAD_DIR, template.storedName);
    const content = fs.readFileSync(filePath, 'utf-8');

    // Execute template (supports .js report generators)
    if (template.storedName.endsWith('.js')) {
      const result = eval(content);
      return { output: result };
    }

    return { output: content };
  }
}
